        "type": "code-recipe",
        "id": "recipe-llamaindex-slim-workflow-hierarchical-rls",
        "heading": "Code Python Production: Chắt lọc LlamaIndex Core Workflows + HierarchicalNodeParser gắn bảo mật Tenant",
        "language": "python",
        "filename": "slim_rag_workflow.py",
        "description": "Minh họa cách DOMATION chỉ sử dụng `llama_index.core.workflow` và `HierarchicalNodeParser` sạch gọn: vừa hưởng lợi cấu trúc Parent-Child chunking và luồng sự kiện async rõ ràng, vừa cưỡng bức lọc `tenant_id` và giữ toàn quyền kiểm soát prompt.",
        "code": "# requirements.txt: pin chính xác để chống dependency churn\n# llama-index-core==0.12.15\n# llama-index-workflows==0.2.0\n\nimport asyncio\nfrom llama_index.core.node_parser import HierarchicalNodeParser, get_leaf_nodes\nfrom llama_index.core.schema import Document, TextNode\nfrom llama_index.core.workflow import Context, Event, StartEvent, StopEvent, Workflow, step\n\nclass RetrievedEvent(Event):\n    tenant_id: str\n    query: str\n    parent_contexts: list[str]\n\ndef build_hierarchical_nodes(raw_markdown: str, tenant_id: str, doc_id: str) -> tuple[list[TextNode], list[TextNode]]:\n    parser = HierarchicalNodeParser.from_defaults(chunk_sizes=[1024, 384, 160])\n    doc = Document(text=raw_markdown, metadata={\"tenant_id\": tenant_id, \"doc_id\": doc_id})\n    all_nodes = parser.get_nodes_from_documents([doc])\n    leaf_nodes = get_leaf_nodes(all_nodes)  # Chỉ embed các leaf 160 token để recall sắc nét\n    return all_nodes, leaf_nodes\n\nclass EnterpriseTenantRagWorkflow(Workflow):\n    @step\n    async def retrieve_and_merge_parents(self, ctx: Context, ev: StartEvent) -> RetrievedEvent:\n        tenant_id = ev.get(\"tenant_id\")\n        query = ev.get(\"query\")\n        if not tenant_id:\n            raise PermissionError(\"Missing tenant_id for RLS-scoped RAG lookup.\")\n\n        # Thực tế gọi PostgreSQL pgvector trong transaction đã SET LOCAL app.current_tenant_id\n        # và gộp ngược từ các leaf nodes khớp lên parent node 1024 token tương ứng\n        matched_parents = [\n            f\"[Tenant={tenant_id}] Chính sách chiết khấu thanh toán nhanh 95% áp dụng đến 30/12...\"\n        ]\n        await ctx.set(\"source_count\", len(matched_parents))\n        return RetrievedEvent(tenant_id=tenant_id, query=query, parent_contexts=matched_parents)\n\n    @step\n    async def synthesize_grounded_answer(self, ctx: Context, ev: RetrievedEvent) -> StopEvent:\n        # Giữ toàn quyền kiểm soát prompt tiếng Việt & model call trực tiếp, không qua Synthesizer ẩn\n        context_block = \"\\n---\\n\".join(ev.parent_contexts)\n        source_count = await ctx.get(\"source_count\", default=0)\n        return StopEvent(result={\n            \"tenant_id\": ev.tenant_id,\n            \"source_count\": source_count,\n            \"prompt_ready_context\": context_block,\n        })\n\nif __name__ == \"__main__\":\n    wf = EnterpriseTenantRagWorkflow(timeout=15.0)\n    res = asyncio.run(wf.run(tenant_id=\"agency_f1_ecolife\", query=\"Chiết khấu 95% áp dụng tới khi nào?\"))\n    print(res)"
