        "description": "Đoạn code chạy hoàn toàn nội bộ trong VPC: ép `artifacts_path` offline không kết nối ra ngoài, bật `TableFormerMode.ACCURATE` giữ nguyên bảng giá gộp ô, và cắt chunk bằng `HybridChunker` kèm `tenant_id` sẵn sàng nạp PostgreSQL pgvector.",
        "code": "from pathlib import Path\nfrom docling.chunking import HybridChunker\nfrom docling.datamodel.base_models import InputFormat\nfrom docling.datamodel.pipeline_options import PdfPipelineOptions, TableFormerMode\nfrom docling.document_converter import DocumentConverter, PdfFormatOption\n\nMODEL_ARTIFACTS_DIR = Path(\"/opt/docling/models\")  # Đã bake sẵn trong Docker image\n\ndef create_private_converter(enable_ocr: bool = False) -> DocumentConverter:\n    pdf_opts = PdfPipelineOptions(\n        artifacts_path=MODEL_ARTIFACTS_DIR,\n        do_ocr=enable_ocr,\n        do_table_structure=True,\n    )\n    pdf_opts.table_structure_options.mode = TableFormerMode.ACCURATE\n    pdf_opts.table_structure_options.do_cell_matching = True\n\n    return DocumentConverter(\n        format_options={\n            InputFormat.PDF: PdfFormatOption(pipeline_options=pdf_opts),\n        }\n    )\n\ndef parse_and_chunk_for_tenant_rag(\n    file_path: str,\n    tenant_id: str,\n    enable_ocr: bool = False,\n) -> dict:\n    converter = create_private_converter(enable_ocr=enable_ocr)\n    conv_result = converter.convert(file_path)\n    dl_doc = conv_result.document\n\n    full_markdown = dl_doc.export_to_markdown()\n    chunker = HybridChunker(max_tokens=450, merge_peers=True)\n\n    rag_records = []\n    for idx, chunk in enumerate(chunker.chunk(dl_doc=dl_doc)):\n        enriched_text = chunker.contextualize(chunk=chunk)\n        page_numbers = sorted({\n            prov.page_no\n            for item in chunk.meta.doc_items\n            for prov in (item.prov or [])\n        })\n        rag_records.append({\n            \"tenant_id\": tenant_id,\n            \"chunk_index\": idx,\n            \"headings\": list(chunk.meta.headings or []),\n            \"page_numbers\": page_numbers,\n            \"content\": enriched_text,\n        })\n\n    return {\n        \"tenant_id\": tenant_id,\n        \"source_file\": Path(file_path).name,\n        \"markdown_preview_chars\": len(full_markdown),\n        \"total_chunks\": len(rag_records),\n        \"chunks\": rag_records,\n    }"
