        "language": "python",
        "filename": "qdrant_multitenant_hybrid.py",
        "description": "Đoạn mã Python sử dụng `qdrant-client` chuẩn hóa mô hình 1 collection dùng chung nhưng tách đồ thị HNSW theo từng đại lý F1 (`m=0`, `payload_m=16`, `is_tenant=True`), nén RAM bằng Binary Quantization kết hợp rescore và truy vấn song song Dense + Sparse qua `Prefetch` + `Fusion.RRF`.",
        "code": "from qdrant_client import QdrantClient, models\n\nclient = QdrantClient(url=\"http://localhost:6333\", timeout=10.0)\nCOLLECTION = \"domation_enterprise_knowledge\"\n\nif not client.collection_exists(COLLECTION):\n    client.create_collection(\n        collection_name=COLLECTION,\n        # Khai bao Named Vectors cho tim kiem kep Dense + Sparse (BM25/BGE-M3)\n        vectors_config={\n            \"dense\": models.VectorParams(\n                size=1536,\n                distance=models.Distance.COSINE,\n                on_disk=True,  # Giu vector float32 goc tren NVMe SSD\n            )\n        },\n        sparse_vectors_config={\n            \"sparse\": models.SparseVectorParams(\n                modifier=models.Modifier.IDF\n            )\n        },\n        # Tat do thi HNSW toan cuc (m=0), chi dung HNSW theo tung tenant (payload_m=16)\n        hnsw_config=models.HnswConfigDiff(\n            m=0,\n            payload_m=16,\n            ef_construct=128,\n        ),\n        # Nen RAM 32x bang Binary Quantization, giu ban nen tren RAM de sang loc nhanh\n        quantization_config=models.BinaryQuantization(\n            binary=models.BinaryQuantizationConfig(always_ram=True)\n        ),\n    )\n\n    # Danh dau is_tenant=True de Qdrant toi uu bo cuc luu tru va sub-index theo dai ly\n    client.create_payload_index(\n        collection_name=COLLECTION,\n        field_name=\"tenant_id\",\n        field_schema=models.KeywordIndexParams(\n            type=models.KeywordIndexType.KEYWORD,\n            is_tenant=True,\n        ),\n    )\n    client.create_payload_index(\n        collection_name=COLLECTION,\n        field_name=\"department\",\n        field_schema=models.PayloadSchemaType.KEYWORD,\n    )\n\ndef search_tenant_hybrid(\n    tenant_id: str,\n    department: str,\n    dense_vec: list[float],\n    sparse_indices: list[int],\n    sparse_values: list[float],\n    limit: int = 8,\n):\n    # Bo loc bat buoc tiem tu JWT/Session da xac thuc o API Gateway\n    tenant_filter = models.Filter(\n        must=[\n            models.FieldCondition(key=\"tenant_id\", match=models.MatchValue(value=tenant_id)),\n            models.FieldCondition(key=\"department\", match=models.MatchValue(value=department)),\n        ]\n    )\n\n    res = client.query_points(\n        collection_name=COLLECTION,\n        prefetch=[\n            models.Prefetch(\n                query=dense_vec,\n                using=\"dense\",\n                filter=tenant_filter,\n                limit=40,\n                params=models.SearchParams(\n                    quantization=models.QuantizationSearchParams(\n                        rescore=True,\n                        oversampling=2.5,\n                    )\n                ),\n            ),\n            models.Prefetch(\n                query=models.SparseVector(indices=sparse_indices, values=sparse_values),\n                using=\"sparse\",\n                filter=tenant_filter,\n                limit=40,\n            ),\n        ],\n        query=models.FusionQuery(fusion=models.Fusion.RRF),\n        limit=limit,\n        with_payload=True,\n    )\n    return res.points"
