        "code": "import asyncio\nimport os\nfrom datetime import datetime, timezone\nfrom graphiti_core import Graphiti\nfrom graphiti_core.nodes import EpisodeType\n\nasync def audit_bitemporal_policies():\n    graphiti = Graphiti(\n        os.getenv(\"NEO4J_URI\", \"bolt://localhost:7687\"),\n        os.getenv(\"NEO4J_USER\", \"neo4j\"),\n        os.getenv(\"NEO4J_PASSWORD\", \"strong_password\"),\n    )\n    try:\n        # Chay 1 lan khi khoi tao DB de tao index vector, BM25 va rang buoc UUID\n        await graphiti.build_indices_and_constraints()\n\n        # 1. Episode ngay 01/11: Mo uu dai dot 1 (chiet khau 8%)\n        await graphiti.add_episode(\n            name=\"ecolife_policy_nov_01\",\n            episode_body=(\n                \"Tu ngay 01/11/2026 den het 15/11/2026, Du an EcoLife Signature \" \n                \"ap dung chiet khau thanh toan som 8% cho toa S2 va tang voucher noi that.\"\n            ),\n            source=EpisodeType.text,\n            source_description=\"Thong bao chinh sach ban hang Dot 1\",\n            reference_time=datetime(2026, 11, 1, 9, 0, tzinfo=timezone.utc),\n            group_id=\"tenant_capital_ecolife\",\n        )\n\n        # 2. Episode ngay 16/11: Chinh sach moi phu dinh muc 8% cu\n        await graphiti.add_episode(\n            name=\"ecolife_policy_nov_16\",\n            episode_body=(\n                \"Cap nhat tu 16/11/2026: Chinh sach chiet khau thanh toan som 8% va tang \" \n                \"voucher noi that cho toa S2 da HET HIEU LUC. Chiet khau moi la 5%.\"\n            ),\n            source=EpisodeType.text,\n            source_description=\"Thong bao dieu chinh chinh sach Dot 2\",\n            reference_time=datetime(2026, 11, 16, 8, 30, tzinfo=timezone.utc),\n            group_id=\"tenant_capital_ecolife\",\n        )\n\n        # 3. Truy van khi khach hoi lai cum tu nhay cam 'chiet khau 8%'\n        edges = await graphiti.search(\n            query=\"Toa S2 EcoLife Signature hien con chiet khau thanh toan som 8% khong?\",\n            group_ids=[\"tenant_capital_ecolife\"],\n            num_results=6,\n        )\n\n        active_facts = [e for e in edges if e.invalid_at is None]\n        expired_facts = [e for e in edges if e.invalid_at is not None]\n\n        print(\"--- SU THAT DANG CON HIEU LUC (Dua vao Prompt) ---\")\n        for edge in active_facts:\n            print(f\"[ACTIVE since {edge.valid_at}] {edge.fact}\")\n\n        print(\"--- SU THAT DA HET HAN (Chan AI khong hua nham) ---\")\n        for edge in expired_facts:\n            print(f\"[INVALIDATED at {edge.invalid_at}] {edge.fact}\")\n    finally:\n        await graphiti.close()\n\nif __name__ == \"__main__\":\n    asyncio.run(audit_bitemporal_policies())"
