        "type": "code-recipe",
        "id": "code-recipe-chroma-poc-and-export-migration",
        "heading": "Code Recipe: Dựng PoC Chroma trong 15 phút & Script xuất Vector sang pgvector/Qdrant không cần Re-Embed",
        "language": "python",
        "filename": "chroma_poc_to_prod_migrator.py",
        "description": "Phần 1 khởi chạy `chromadb.PersistentClient` cực gọn cho sprint thử nghiệm; Phần 2 minh họa cách trích xuất theo lô vector đã nhúng sẵn (`include=['embeddings', 'documents', 'metadatas']`) để di chuyển lên PostgreSQL pgvector FORCE RLS hoặc Qdrant mà không tốn thêm chi phí Embedding API.",
        "code": "import chromadb\nfrom typing import Iterator\n\n# --- PHA 1: VIBECODE POC TRONG 15 PHUT VOI CHROMA RUST CORE ---\ndef run_15min_poc_demo():\n    # Chay nhung ngay trong process Python, khong can bat container rieng\n    client = chromadb.PersistentClient(path=\"./chroma_poc_data\")\n    collection = client.get_or_create_collection(\n        name=\"ecolife_sales_policy_poc\",\n        metadata={\"hnsw:space\": \"cosine\"},\n    )\n\n    collection.upsert(\n        ids=[\"doc_01\", \"doc_02\", \"doc_03\"],\n        documents=[\n            \"Chinh sach thanh toan chuan toa S1 chia lam 7 dot, chiet khau 3%.\",\n            \"Can ho 2PN+ dien tich 74m2 ban cong Dong Nam gia tu 3.2 ty.\",\n            \"Quy trinh dat coc giu cho 50 trieu VNĐ qua tai khoan chu dau tu.\",\n        ],\n        metadatas=[\n            {\"tenant_id\": \"ecolife_dn\", \"doc_type\": \"policy\"},\n            {\"tenant_id\": \"ecolife_dn\", \"doc_type\": \"inventory\"},\n            {\"tenant_id\": \"ecolife_dn\", \"doc_type\": \"booking\"},\n        ],\n    )\n\n    # Truy van thu nghiem voi bo loc metadata where\n    hits = collection.query(\n        query_texts=[\"Can 2 ngu cong huong Dong Nam gia bao nhieu?\"],\n        n_results=2,\n        where={\"tenant_id\": \"ecolife_dn\"},\n    )\n    return hits\n\n# --- PHA 2: DI CHUYEN SANG PGVECTOR FORCE RLS / QDRANT KHONG TON TIEN RE-EMBED ---\ndef export_chroma_batches(path: str, collection_name: str, batch_size: int = 500) -> Iterator[dict]:\n    client = chromadb.PersistentClient(path=path)\n    collection = client.get_collection(name=collection_name)\n    total = collection.count()\n\n    for offset in range(0, total, batch_size):\n        batch = collection.get(\n            limit=batch_size,\n            offset=offset,\n            include=[\"embeddings\", \"documents\", \"metadatas\"],\n        )\n        for idx, doc_id in enumerate(batch[\"ids\"]):\n            yield {\n                \"external_id\": doc_id,\n                \"tenant_id\": (batch[\"metadatas\"][idx] or {}).get(\"tenant_id\", \"default\"),\n                \"content\": batch[\"documents\"][idx],\n                \"metadata\": batch[\"metadatas\"][idx],\n                # Giu nguyen vector float da nhung san de day thang sang pgvector / Qdrant\n                \"embedding\": list(batch[\"embeddings\"][idx]),\n            }\n\nif __name__ == \"__main__\":\n    print(\"PoC Query Hits:\", run_15min_poc_demo()[\"documents\"])"
